() => {
  const { search, hash } = useLocation();
  if (search && search.length > 1) {
    return <Navigate to={`${APP_ROUTES.PROPERTY_BROWSE}${search}${hash}`} replace />;
  }
  return <Pages.PropertyLanding />;
}

